-- 100 reusable news templates. They remain private until an event renders one.
alter table public.news_posts add column if not exists source_key text;
create unique index if not exists news_posts_source_key_uq on public.news_posts(source_key) where source_key is not null;
create table if not exists public.news_templates (id uuid primary key default gen_random_uuid(), template_key text not null unique, event_type text not null, title_template text not null, body_template text not null, category text not null default 'Competicion', enabled boolean not null default true, created_at timestamptz not null default now());
create index if not exists news_templates_event_idx on public.news_templates(event_type,enabled);
alter table public.news_templates enable row level security;
revoke all on public.news_templates from anon, authenticated;
create or replace function public.publish_template_news(p_event_type text,p_vars jsonb default '{}'::jsonb,p_source_key text default null) returns uuid language plpgsql security definer set search_path='' as $$ declare t record; k record; title_text text; body_text text; result_id uuid; begin if p_source_key is not null then select id into result_id from public.news_posts where source_key=p_source_key limit 1; if result_id is not null then return result_id; end if; end if; select * into t from public.news_templates where event_type=p_event_type and enabled order by random() limit 1; if not found then return null; end if; title_text:=t.title_template; body_text:=t.body_template; for k in select key,value from jsonb_each_text(coalesce(p_vars,'{}'::jsonb)) loop title_text:=replace(title_text,'{'||k.key||'}',k.value); body_text:=replace(body_text,'{'||k.key||'}',k.value); end loop; insert into public.news_posts(title,body,category,published,source_key) values(left(title_text,140),body_text,t.category,true,p_source_key) returning id into result_id; return result_id; exception when others then return null; end; $$;
with g as (select n,(array['MARKET_WIN','BUY','SELL','PROTECT','LINEUP','RESULT','MARKET_OPEN','MARKET_CLOSE'])[((n-1)%8)+1] event_type,(array['Yegu07','Splendy','Aizen','Cano','Piolin','Phoski','DemonShark','Mago','StarLax','ElJuan123'])[((n-1)%10)+1] pilot,(array['lluvia','cometa','eclipse','aurora','luna','constelacion','anillo','via_lactea','supernova','estrella'])[((n-1)%10)+1] phenomenon from generate_series(1,100) x(n)) insert into public.news_templates(template_key,event_type,title_template,body_template,category) select 'ATLAS-LEGEND-'||lpad(n::text,3,'0'),event_type,case event_type when 'MARKET_WIN' then '[LEYENDA] {USUARIO} gana a {PILOTO}' when 'BUY' then '[LEYENDA] {USUARIO} ficha a {PILOTO}' when 'SELL' then '[LEYENDA] {USUARIO} vende a {PILOTO}' when 'PROTECT' then '[LEYENDA] {PILOTO} queda protegido' when 'LINEUP' then '[LEYENDA] Alineacion de {EQUIPO}' when 'RESULT' then '[LEYENDA] {PILOTO} deja su firma' when 'MARKET_OPEN' then '[LEYENDA] Mercado abierto' else '[LEYENDA] Mercado cerrado' end,case event_type when 'MARKET_WIN' then '{USUARIO} gano a {PILOTO} por {IMPORTE} EUR bajo la '||phenomenon when 'BUY' then '{USUARIO} incorporo a {PILOTO} por {IMPORTE} EUR; la '||phenomenon||' brillo en Atlas' when 'SELL' then '{USUARIO} vendio a {PILOTO} por {IMPORTE} EUR entre luces de '||phenomenon when 'PROTECT' then '{USUARIO} protegio a {PILOTO} bajo una '||phenomenon when 'LINEUP' then '{USUARIO} bloqueo la alineacion de {EQUIPO} para {JORNADA}; aparecio una '||phenomenon when 'RESULT' then '{PILOTO} sumo {PUNTOS} puntos en {JORNADA} y activo la '||phenomenon when 'MARKET_OPEN' then 'El mercado abre con una '||phenomenon||' sobre Atlas' else 'El mercado cierra bajo la '||phenomenon end,case when event_type in ('MARKET_WIN','BUY','SELL','PROTECT','MARKET_OPEN','MARKET_CLOSE') then 'Mercado' else 'Competicion' end from g on conflict (template_key) do nothing;
create or replace function public.publish_team_transaction_news() returns trigger language plpgsql security definer set search_path='' as $$ declare team_name text; owner_name text; player_name text; ev text; made uuid; begin begin select ft.name,coalesce(p.display_name,ft.name) into team_name,owner_name from public.fantasy_teams ft left join public.profiles p on p.id=ft.user_id where ft.id=new.fantasy_team_id; select p.name into player_name from public.players p where p.id=new.player_id; ev:=case when new.type='PILOT_MARKET_SALE'::public.transaction_type then 'SELL' when new.type='CLAUSE_PURCHASE'::public.transaction_type then 'BUY' when new.type='CLAUSE_PROTECTION'::public.transaction_type then 'PROTECT' end; if ev is not null then made:=public.publish_template_news(ev,jsonb_build_object('USUARIO',coalesce(owner_name,team_name),'EQUIPO',team_name,'PILOTO',player_name,'IMPORTE',to_char(new.amount,'FM999G999G999G990')),'transaction:'||new.id::text); end if; exception when others then null; end; return new; end; $$;
create or replace function public.publish_market_result_news() returns trigger language plpgsql security definer set search_path='' as $$ declare pn text;tn text;onm text;wk date;paid bigint;made uuid; begin select p.name,o.week_start into pn,wk from public.players p join public.market_offers o on o.id=new.market_offer_id; select ft.name,coalesce(pr.display_name,ft.name) into tn,onm from public.fantasy_teams ft left join public.profiles pr on pr.id=ft.user_id where ft.id=new.fantasy_team_id; select coalesce(new.winning_amount,b.amount) into paid from public.market_bids b where b.id=new.winning_bid_id; made:=public.publish_template_news('MARKET_WIN',jsonb_build_object('USUARIO',coalesce(onm,tn),'EQUIPO',tn,'PILOTO',pn,'IMPORTE',to_char(paid,'FM999G999G999G990'),'JORNADA',wk::text),'market-result:'||new.id::text); return new; exception when others then return new; end; $$;
create or replace function public.publish_lineup_news() returns trigger language plpgsql security definer set search_path='' as $$ declare tn text;onm text;mn text;made uuid; begin if new.locked_at is null or old.locked_at is not null then return new; end if; select ft.name,coalesce(p.display_name,ft.name) into tn,onm from public.fantasy_teams ft left join public.profiles p on p.id=ft.user_id where ft.id=new.fantasy_team_id; select md.name into mn from public.matchdays md where md.id=new.matchday_id; made:=public.publish_template_news('LINEUP',jsonb_build_object('USUARIO',coalesce(onm,tn),'EQUIPO',tn,'JORNADA',coalesce(mn,'la proxima jornada')),'lineup:'||new.id::text); return new; exception when others then return new; end; $$;
